import { IngestPipeline } from "@514labs/moose-lib";

// Data model for user activity events
export interface UserActivityEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number | null; // nullable, will default to 0 in views
}

// Create the ingest pipeline with proper table ordering
export const UserActivityEventPipeline = new IngestPipeline<UserActivityEvent>("UserActivityEvent", {
  table: { orderByFields: ["user_id", "event_ts"] },
  stream: true,
  ingestApi: true,
});

